import React ,{useState}from "react";
import axios from "axios";
import { Link,navigate } from "react-router-dom";
export default function SignupPage() {
 // const [data, setData]=useState();
 const[message,setMessage]=useState("");
   const navigate = useNavigate(); 
  const [form, setForm]=useState({name:"",email:"",password:"",cpassword:""});
  const Validate = {
  name: (v) => {
    if (!v.trim()) return "Name is required.";
    if (v.trim().length < 5) return "Name must be at least 5 characters.";
    return "";
  },
  email: (v) => {
    if (!v.trim()) return "Email is required.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))
      return "Invalid email format.";
    return "";
  },
  password: (v) => {
    if (!v.trim()) return "Password is required.";
    if (v.length < 6) return "Password must be at least 6 characters.";
    return "";
  },

  cpassword: (pass, cpass) => {
    if (pass !== cpass) return "Passwords do not match.";
    return "";
  },
};
const handleForm = (e) => {
  setForm({ ...form, [e.target.name]: e.target.value });
   setMessage("");
};
  const handleSubmit = async (e) => {
  e.preventDefault();
  

  const nameError = Validate.name(form.name);
  const emailError = Validate.email(form.email);
  const passError = Validate.password(form.password);
  const cpassError = Validate.cpassword(form.password, form.cpassword);

  if (nameError || emailError || passError || cpassError) {
    setMessage(nameError || emailError || passError || cpassError);
    return;
  }

  try {
    const res = await axios.post("http://localhost:5000/signup", form);
    setMessage(res.data.message);
    
  } catch (err) {
    setMessage(err.response?.data?.message || "Server error");
  }
};


  return (
    <div id ="signup" style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>Create Account </h2>
        <p style={styles.subtitle}>Join DailyCode and start coding smarter</p>
        <form style={styles.form} onSubmit={handleSubmit}>
          <input
            type="text"
            name="name"
            placeholder="Enter Full Name"
            value={form.name}
            style={styles.input}
            onChange={handleForm}
            

     />
        <input
            type="text"
            name="email"
            placeholder="Enter the Email"
            style={styles.input}
            value={form.email}
            onChange={handleForm}
          
          />
          <input
            type="password"
            onChange={handleForm}
            placeholder="Password"
            name="password"
            value={form.password}
            style={styles.input}
          
          />
          <input
            type="password"
            onChange={handleForm}
            name="cpassword"
            value={form.cpassword}
            placeholder="Confirm Password"
            style={styles.input}
            
          />

          <button type="submit"  onClick={() => navigate("/login")} style={styles.button}>
            Sign Up
          </button>
        </form>
        <p style={styles.message1}>{message}</p>
        <p style={styles.footer}>
          Already have an account?{" "}
          <Link to="/login" style={styles.link}>Log in</Link>

        </p>
      </div>
    </div>
  );
}

const styles = {
  container: {
    width:"110vw",
    height: "100vh",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: "linear-gradient(135deg, #232b3dff, #1e3a8a)", // dark gradient
    fontFamily: "sans-serif",
    padding: "1rem",
  },
    message1:{
    color:"red",
    fontSize:"20px",
    fontWeight:"500",
   } ,
  card: {
    background: "rgba(255, 255, 255, 0.1)", // glassmorphism
    backdropFilter: "blur(12px)",
    borderRadius: "16px",
    padding: "2rem",
    width: "100%",
    height:"700px",
    maxWidth: "620px",
    color: "white",
    boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
    textAlign: "center",
  },

  title: {
    fontSize: "2.8rem",
    fontWeight: "bold",
    marginBottom: "0.5rem",
    color: "#38bdf8", // accent cyan
  },

  subtitle: {
    fontSize: "0.95rem",
    marginBottom: "1.5rem",
    fontSize:"1.5rem",
    color: "#e5e7eb",
  },

  form: {
    display: "flex",
    flexDirection: "column",
    gap: "2rem",
    alignItems:"center"
  },

  input: {
    padding: "1rem",
    borderRadius: "8px",
    border: "none",
    width:"90%",
    outline: "none",
    fontSize: "1.5rem",
    background: "rgba(255,255,255,0.2)",
    color: "white",
    transition: "0.3s",
  },

  button: {
    padding: "0.9rem",
    borderRadius: "8px",
    border: "none",
    background: "linear-gradient(135deg, #38bdf8, #2563eb)",
    color: "white",
    fontSize: "1.5rem",
    fontWeight: "bold",
    cursor: "pointer",
    width:"90%",
    transition: "0.3s",
  },

  footer: {
    marginTop: "1.5rem",
    fontSize: "1.5rem",
    color: "#d1d5db",
  },

  link: {
    color: "#38bdf8",
    textDecoration: "none",
    fontWeight: "bold",
  },
};
